CREATE FUNCTION clinlims.guard_training_laboratory_number_reset() RETURNS integer
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, clinlims AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM clinlims.site_information WHERE name='TrainingInstallation' AND lower(trim(value))='true') THEN
   RAISE EXCEPTION 'Laboratory numbers may only be reset in a training installation';
 END IF;
 LOCK TABLE clinlims.sample, clinlims.sample_item IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS (SELECT 1 FROM clinlims.sample) OR EXISTS (SELECT 1 FROM clinlims.sample_item) THEN
   RAISE EXCEPTION 'Clear clinical data before resetting laboratory numbers';
 END IF;
 RETURN 1;
END;
$$;
